public class PointTester1 {
	public static void main(String[] args) {
		Point1 point = new Point1();
		point.setX(7);
		point.setY(2);
		point.translate(11, 6);
		System.out.println("Ehdathiyat al-nuqta: (" + point.getX() + ", " + point.getY() + ")") ;
	}
}
class Point1 {
	// Khatwa 1: 'Ilan al-mutaghayyirat al-instansiya
	private int x;
	private int y;
	// Khatwa 2: 'Ilan al-method li-tahwil mawqi' al-nuqta bi al-kammiyya al-mu'ayyana
	public void translate(int dx, int dy) {
		x += dx;
		y += dy;
	}
	// Khatwa 3: Ta'reef methods set w get li-mu'ayyinat x lil-nuqta
	public void setX(int newX) {
		x = newX;
	}
	public int getX() {
		return x;
	}
	// Khatwa 4: Ta'reef methods set w get li-mu'ayyinat y lil-nuqta
	public void setY(int newY) {
		y = newY;
	}
	public int getY() {
		return y;
	}
}
